INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (10, "", "", 0, 0, 320, 0, 23001, 2, 20001, 20);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", "リリ", 1, 0, 321, 125801, 24001, 2, 40011, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", "クリア", 1, 0, 322, 126001, 24001, 2, 40011, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (3, "んーと。\nこれ、あげる。\nはい", "プレシア", 1, 0, 323, 126101, 24001, 2, 40011, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (4, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", "リリ", 2, 0, 324, 125801, 24001, 2, 40011, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (5, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", "クリア", 2, 0, 325, 126001, 24001, 2, 40011, 1);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (6, "お兄。\nきてくれて、うれしい", "プレシア", 2, 0, 326, 126101, 24001, 2, 40011, 1);
